-- 0001_init: core schema. Money is INTEGER minor units; times are INTEGER
-- unix milliseconds UTC; ids are UUIDv7 text generated by the domain layer.

CREATE TABLE persons (
  id            TEXT PRIMARY KEY,
  login         TEXT NOT NULL UNIQUE,
  password_hash TEXT NOT NULL,
  created_at    INTEGER NOT NULL
);

CREATE TABLE login_throttle (
  login        TEXT PRIMARY KEY,
  failures     INTEGER NOT NULL,
  locked_until INTEGER NOT NULL
);

CREATE TABLE sessions (
  id           TEXT PRIMARY KEY,
  person_id    TEXT NOT NULL REFERENCES persons(id),
  created_at   INTEGER NOT NULL,
  last_seen_at INTEGER NOT NULL,
  expires_at   INTEGER NOT NULL,
  revoked_at   INTEGER
);
CREATE INDEX sessions_person ON sessions(person_id);

CREATE TABLE networks (
  id         TEXT PRIMARY KEY,
  name       TEXT NOT NULL,
  slug       TEXT NOT NULL UNIQUE,
  status     TEXT NOT NULL CHECK (status IN ('setup','active','closed')),
  ledger_seq INTEGER NOT NULL DEFAULT 0,
  created_at INTEGER NOT NULL
);

CREATE TABLE network_policies (
  network_id   TEXT NOT NULL REFERENCES networks(id),
  version      INTEGER NOT NULL,
  policy_json  TEXT NOT NULL,
  changed_by   TEXT NOT NULL DEFAULT '',
  reason       TEXT NOT NULL DEFAULT '',
  effective_at INTEGER NOT NULL,
  PRIMARY KEY (network_id, version)
);

CREATE TABLE api_tokens (
  id           TEXT PRIMARY KEY,
  person_id    TEXT NOT NULL REFERENCES persons(id),
  network_id   TEXT REFERENCES networks(id),
  name         TEXT NOT NULL,
  token_hash   TEXT NOT NULL UNIQUE,
  scopes       TEXT NOT NULL,
  created_at   INTEGER NOT NULL,
  last_used_at INTEGER,
  expires_at   INTEGER,
  revoked_at   INTEGER
);

CREATE TABLE members (
  id           TEXT PRIMARY KEY,
  network_id   TEXT NOT NULL REFERENCES networks(id),
  person_id    TEXT NOT NULL REFERENCES persons(id),
  display_name TEXT NOT NULL,
  status       TEXT NOT NULL CHECK (status IN ('pending','active','suspended','departed')),
  join_method  TEXT NOT NULL,
  default_flag INTEGER NOT NULL DEFAULT 0 CHECK (default_flag IN (0,1)),
  joined_at    INTEGER NOT NULL,
  departed_at  INTEGER,
  UNIQUE (network_id, person_id),
  UNIQUE (network_id, id)
);

CREATE TABLE role_assignments (
  id         TEXT PRIMARY KEY,
  network_id TEXT NOT NULL,
  member_id  TEXT NOT NULL,
  role       TEXT NOT NULL CHECK (role IN ('admin','reviewer')),
  granted_at INTEGER NOT NULL,
  granted_by TEXT NOT NULL DEFAULT '',
  revoked_at INTEGER,
  FOREIGN KEY (network_id, member_id) REFERENCES members(network_id, id)
);
CREATE UNIQUE INDEX role_live ON role_assignments(member_id, role) WHERE revoked_at IS NULL;

CREATE TABLE accounts (
  id                   TEXT PRIMARY KEY,
  network_id           TEXT NOT NULL REFERENCES networks(id),
  member_id            TEXT UNIQUE,
  is_system            INTEGER NOT NULL DEFAULT 0 CHECK (is_system IN (0,1)),
  balance              INTEGER NOT NULL DEFAULT 0,
  limit_override       INTEGER CHECK (limit_override IS NULL OR limit_override >= 0),
  limit_override_until INTEGER,
  UNIQUE (network_id, id),
  FOREIGN KEY (network_id, member_id) REFERENCES members(network_id, id),
  CHECK ((is_system = 1 AND member_id IS NULL) OR (is_system = 0 AND member_id IS NOT NULL))
);
CREATE UNIQUE INDEX one_system_account ON accounts(network_id) WHERE is_system = 1;

CREATE TABLE invitations (
  id         TEXT PRIMARY KEY,
  network_id TEXT NOT NULL REFERENCES networks(id),
  token_hash TEXT NOT NULL UNIQUE,
  created_by TEXT NOT NULL,
  created_at INTEGER NOT NULL,
  expires_at INTEGER NOT NULL,
  used_at    INTEGER,
  used_by    TEXT,
  revoked_at INTEGER
);

CREATE TABLE listings (
  id          TEXT PRIMARY KEY,
  network_id  TEXT NOT NULL,
  member_id   TEXT NOT NULL,
  type        TEXT NOT NULL CHECK (type IN ('offer','request')),
  title       TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  price       INTEGER CHECK (price IS NULL OR price > 0),
  status      TEXT NOT NULL CHECK (status IN ('active','paused','archived')),
  created_at  INTEGER NOT NULL,
  updated_at  INTEGER NOT NULL,
  UNIQUE (network_id, id),
  FOREIGN KEY (network_id, member_id) REFERENCES members(network_id, id)
);

CREATE TABLE transactions (
  id               TEXT PRIMARY KEY,
  network_id       TEXT NOT NULL,
  kind             TEXT NOT NULL CHECK (kind IN ('trade','reversal','adjustment','grant')),
  status           TEXT NOT NULL CHECK (status IN
                     ('proposed','completed','declined','cancelled','expired','disputed','reversed')),
  payer_account_id TEXT NOT NULL,
  payee_account_id TEXT NOT NULL,
  amount           INTEGER NOT NULL CHECK (amount > 0),
  listing_id       TEXT,
  note             TEXT NOT NULL DEFAULT '',
  reason           TEXT NOT NULL DEFAULT '',
  original_tx_id   TEXT,
  created_by       TEXT,
  accepted_by      TEXT,
  reversed_total   INTEGER NOT NULL DEFAULT 0,
  proposed_at      INTEGER NOT NULL,
  expires_at       INTEGER,
  completed_at     INTEGER,
  ledger_seq       INTEGER,
  UNIQUE (network_id, id),
  CHECK (payer_account_id <> payee_account_id),
  CHECK (reversed_total >= 0 AND reversed_total <= amount),
  CHECK (kind = 'trade' OR reason <> ''),
  CHECK (kind <> 'reversal' OR original_tx_id IS NOT NULL),
  CHECK (kind = 'reversal' OR original_tx_id IS NULL),
  FOREIGN KEY (network_id, payer_account_id) REFERENCES accounts(network_id, id),
  FOREIGN KEY (network_id, payee_account_id) REFERENCES accounts(network_id, id),
  FOREIGN KEY (network_id, original_tx_id)   REFERENCES transactions(network_id, id),
  FOREIGN KEY (network_id, listing_id)       REFERENCES listings(network_id, id),
  FOREIGN KEY (network_id, created_by)       REFERENCES members(network_id, id),
  FOREIGN KEY (network_id, accepted_by)      REFERENCES members(network_id, id)
);
CREATE INDEX tx_payer  ON transactions(payer_account_id, status);
CREATE INDEX tx_payee  ON transactions(payee_account_id, status);
CREATE INDEX tx_expiry ON transactions(expires_at) WHERE status = 'proposed';
CREATE INDEX tx_orig   ON transactions(original_tx_id) WHERE original_tx_id IS NOT NULL;

CREATE TABLE transaction_status_events (
  id          TEXT PRIMARY KEY,
  network_id  TEXT NOT NULL,
  tx_id       TEXT NOT NULL,
  from_status TEXT NOT NULL,
  to_status   TEXT NOT NULL,
  actor_id    TEXT NOT NULL DEFAULT '',
  request_id  TEXT NOT NULL DEFAULT '',
  occurred_at INTEGER NOT NULL,
  FOREIGN KEY (network_id, tx_id) REFERENCES transactions(network_id, id)
);
CREATE INDEX tx_status_events_tx ON transaction_status_events(tx_id);

CREATE TABLE entries (
  id         TEXT PRIMARY KEY,
  network_id TEXT NOT NULL,
  tx_id      TEXT NOT NULL,
  account_id TEXT NOT NULL,
  amount     INTEGER NOT NULL CHECK (amount <> 0),
  ledger_seq INTEGER NOT NULL,
  posted_at  INTEGER NOT NULL,
  UNIQUE (tx_id, account_id),
  FOREIGN KEY (network_id, tx_id)      REFERENCES transactions(network_id, id),
  FOREIGN KEY (network_id, account_id) REFERENCES accounts(network_id, id)
);
CREATE INDEX entries_account ON entries(account_id, ledger_seq);
CREATE INDEX entries_network ON entries(network_id, ledger_seq);

CREATE TABLE disputes (
  id              TEXT PRIMARY KEY,
  network_id      TEXT NOT NULL,
  tx_id           TEXT NOT NULL,
  opened_by       TEXT NOT NULL,
  category        TEXT NOT NULL,
  statement       TEXT NOT NULL DEFAULT '',
  status          TEXT NOT NULL CHECK (status IN
                    ('open','under_review','posting_pending','resolved','withdrawn')),
  outcome         TEXT CHECK (outcome IS NULL OR outcome IN ('dismissed','upheld','partially_upheld')),
  reversal_amount INTEGER NOT NULL DEFAULT 0 CHECK (reversal_amount >= 0),
  reviewer_id     TEXT,
  rationale       TEXT NOT NULL DEFAULT '',
  opened_at       INTEGER NOT NULL,
  decided_at      INTEGER,
  UNIQUE (network_id, id),
  FOREIGN KEY (network_id, tx_id)     REFERENCES transactions(network_id, id),
  FOREIGN KEY (network_id, opened_by) REFERENCES members(network_id, id)
);
CREATE UNIQUE INDEX dispute_live ON disputes(tx_id)
  WHERE status IN ('open','under_review','posting_pending');

CREATE TABLE dispute_events (
  id          TEXT PRIMARY KEY,
  network_id  TEXT NOT NULL,
  dispute_id  TEXT NOT NULL,
  actor_id    TEXT NOT NULL DEFAULT '',
  action      TEXT NOT NULL,
  outcome     TEXT NOT NULL DEFAULT '',
  occurred_at INTEGER NOT NULL,
  FOREIGN KEY (network_id, dispute_id) REFERENCES disputes(network_id, id)
);

CREATE TABLE audit_events (
  id             TEXT PRIMARY KEY,
  network_id     TEXT NOT NULL,           -- '' = platform scope
  seq            INTEGER NOT NULL,
  occurred_at    INTEGER NOT NULL,
  actor_type     TEXT NOT NULL,
  actor_id       TEXT NOT NULL DEFAULT '',
  action         TEXT NOT NULL,
  target_type    TEXT NOT NULL,
  target_id      TEXT NOT NULL,
  request_id     TEXT NOT NULL DEFAULT '',
  idem_ref       TEXT NOT NULL DEFAULT '',
  summary_before TEXT NOT NULL DEFAULT '',
  summary_after  TEXT NOT NULL DEFAULT '',
  reason         TEXT NOT NULL DEFAULT '',
  prev_hash      TEXT NOT NULL DEFAULT '',
  hash           TEXT NOT NULL,
  UNIQUE (network_id, seq)
);
CREATE INDEX audit_target ON audit_events(network_id, target_id);

CREATE TABLE audit_subjects (
  audit_id   TEXT NOT NULL REFERENCES audit_events(id),
  network_id TEXT NOT NULL,
  member_id  TEXT NOT NULL,
  PRIMARY KEY (audit_id, member_id)
);
CREATE INDEX audit_subjects_member ON audit_subjects(network_id, member_id);

CREATE TABLE idempotency_keys (
  network_id  TEXT NOT NULL,              -- '' = platform scope
  actor_id    TEXT NOT NULL,
  operation   TEXT NOT NULL,
  key         TEXT NOT NULL,
  fingerprint TEXT NOT NULL,
  result_ref  TEXT NOT NULL,
  created_at  INTEGER NOT NULL,
  expires_at  INTEGER NOT NULL,
  PRIMARY KEY (network_id, actor_id, operation, key)
);

CREATE TABLE consistency_runs (
  id          TEXT PRIMARY KEY,
  network_id  TEXT NOT NULL REFERENCES networks(id),
  started_at  INTEGER NOT NULL,
  finished_at INTEGER NOT NULL,
  ok          INTEGER NOT NULL,
  findings    TEXT NOT NULL
);

-- ---------------------------------------------------------------------
-- LED-2 / DAT-010: append-only tables. No UPDATE or DELETE, ever.
-- ---------------------------------------------------------------------
CREATE TRIGGER entries_no_update BEFORE UPDATE ON entries
BEGIN SELECT RAISE(ABORT, 'entries are append-only'); END;
CREATE TRIGGER entries_no_delete BEFORE DELETE ON entries
BEGIN SELECT RAISE(ABORT, 'entries are append-only'); END;

CREATE TRIGGER audit_no_update BEFORE UPDATE ON audit_events
BEGIN SELECT RAISE(ABORT, 'audit_events are append-only'); END;
CREATE TRIGGER audit_no_delete BEFORE DELETE ON audit_events
BEGIN SELECT RAISE(ABORT, 'audit_events are append-only'); END;

CREATE TRIGGER audit_subjects_no_update BEFORE UPDATE ON audit_subjects
BEGIN SELECT RAISE(ABORT, 'audit_subjects are append-only'); END;
CREATE TRIGGER audit_subjects_no_delete BEFORE DELETE ON audit_subjects
BEGIN SELECT RAISE(ABORT, 'audit_subjects are append-only'); END;

CREATE TRIGGER status_events_no_update BEFORE UPDATE ON transaction_status_events
BEGIN SELECT RAISE(ABORT, 'transaction_status_events are append-only'); END;
CREATE TRIGGER status_events_no_delete BEFORE DELETE ON transaction_status_events
BEGIN SELECT RAISE(ABORT, 'transaction_status_events are append-only'); END;

CREATE TRIGGER dispute_events_no_update BEFORE UPDATE ON dispute_events
BEGIN SELECT RAISE(ABORT, 'dispute_events are append-only'); END;
CREATE TRIGGER dispute_events_no_delete BEFORE DELETE ON dispute_events
BEGIN SELECT RAISE(ABORT, 'dispute_events are append-only'); END;

CREATE TRIGGER consistency_runs_no_update BEFORE UPDATE ON consistency_runs
BEGIN SELECT RAISE(ABORT, 'consistency_runs are append-only'); END;
CREATE TRIGGER consistency_runs_no_delete BEFORE DELETE ON consistency_runs
BEGIN SELECT RAISE(ABORT, 'consistency_runs are append-only'); END;

CREATE TRIGGER policies_no_update BEFORE UPDATE ON network_policies
BEGIN SELECT RAISE(ABORT, 'network_policies are append-only'); END;
CREATE TRIGGER policies_no_delete BEFORE DELETE ON network_policies
BEGIN SELECT RAISE(ABORT, 'network_policies are append-only'); END;

CREATE TRIGGER roles_no_delete BEFORE DELETE ON role_assignments
BEGIN SELECT RAISE(ABORT, 'role_assignments are append-only'); END;

-- ---------------------------------------------------------------------
-- Transaction integrity (DOM-009, DOM-013, DOM-015, DAT-007)
-- ---------------------------------------------------------------------
CREATE TRIGGER tx_insert_proposed BEFORE INSERT ON transactions
WHEN NEW.status <> 'proposed'
BEGIN SELECT RAISE(ABORT, 'transactions are inserted as proposed and completed by posting'); END;

CREATE TRIGGER tx_no_delete BEFORE DELETE ON transactions
BEGIN SELECT RAISE(ABORT, 'transactions are never deleted'); END;

CREATE TRIGGER tx_terms_immutable BEFORE UPDATE ON transactions
WHEN NEW.id <> OLD.id OR NEW.network_id <> OLD.network_id OR NEW.kind <> OLD.kind
  OR NEW.payer_account_id <> OLD.payer_account_id OR NEW.payee_account_id <> OLD.payee_account_id
  OR NEW.amount <> OLD.amount OR NEW.proposed_at <> OLD.proposed_at
  OR NEW.reason <> OLD.reason OR NEW.original_tx_id IS NOT OLD.original_tx_id
  OR NEW.listing_id IS NOT OLD.listing_id OR NEW.created_by IS NOT OLD.created_by
  OR NEW.expires_at IS NOT OLD.expires_at
BEGIN SELECT RAISE(ABORT, 'transaction terms are immutable'); END;

CREATE TRIGGER tx_status_flow BEFORE UPDATE OF status ON transactions
WHEN NEW.status <> OLD.status AND NOT (
     (OLD.status = 'proposed'  AND NEW.status IN ('completed','declined','cancelled','expired'))
  OR (OLD.status = 'completed' AND NEW.status IN ('disputed','reversed'))
  OR (OLD.status = 'disputed'  AND NEW.status IN ('completed','reversed')))
BEGIN SELECT RAISE(ABORT, 'illegal transaction status transition'); END;

CREATE TRIGGER tx_complete_needs_entries BEFORE UPDATE OF status ON transactions
WHEN NEW.status = 'completed' AND OLD.status = 'proposed'
 AND ( (SELECT COUNT(*) FROM entries WHERE tx_id = NEW.id) <> 2
    OR (SELECT COALESCE(SUM(amount), 0) FROM entries WHERE tx_id = NEW.id) <> 0
    OR (SELECT COUNT(*) FROM entries e WHERE e.tx_id = NEW.id AND
         ((e.account_id = NEW.payer_account_id AND e.amount = -NEW.amount) OR
          (e.account_id = NEW.payee_account_id AND e.amount =  NEW.amount))) <> 2 )
BEGIN SELECT RAISE(ABORT, 'completed transaction needs exactly two balanced entries'); END;

CREATE TRIGGER entries_only_for_open_tx BEFORE INSERT ON entries
WHEN NOT EXISTS (SELECT 1 FROM transactions t
   WHERE t.id = NEW.tx_id AND t.network_id = NEW.network_id AND t.status = 'proposed'
     AND ((t.payer_account_id = NEW.account_id AND NEW.amount = -t.amount)
       OR (t.payee_account_id = NEW.account_id AND NEW.amount =  t.amount)))
BEGIN SELECT RAISE(ABORT, 'entry must be one side of a proposed transaction being posted'); END;
